//
// Layout of the compiled-in CLDR tables (locale_tables.cpp, generated by
// tools/gen_locale_tables.py). All strings are NUL-terminated UTF-8 inside
// kPool and are referenced by a uint16_t byte offset; offset 0 is "".

#pragma once

#include <cstdint>

namespace a2ui {
namespace locale {
namespace detail {

/** Indices into LocaleData::months / days. */
enum NameWidth : uint8_t {
  kFormatWide = 0,
  kFormatAbbr,
  kFormatNarrow,
  kStandAloneWide,
  kStandAloneAbbr,
  kStandAloneNarrow,
  kNameWidthCount,
};

struct CurrencySymbol {
  uint16_t text;  // Pool offset.
  uint8_t flags;  // Bit 0: first char is in [[:S:][:Z:]]; bit 1: last char is.
};

struct CurrencyInfo {
  char code[3];
  uint8_t digits;  // ISO 4217 minor units (CLDR currencyData).
  uint8_t symbol;  // Index into kCurrencySymbols for "en"; 255 = the code itself.
};

struct CurrencyOverride {
  uint16_t currency;  // Index into kCurrencies.
  uint8_t symbol;     // Index into kCurrencySymbols.
};

struct LocaleData {
  uint16_t decimal, group, minus;  // Pool offsets (latn number symbols).
  uint8_t min_grouping;            // CLDR minimumGroupingDigits.
  // Currency pattern affixes; "¤" is the symbol, "-" the minus sign.
  // Order: positive prefix, positive suffix, negative prefix, negative suffix.
  uint16_t currency_affix[4];
  uint16_t months[kNameWidthCount];  // Indices into kNames12 (January first).
  uint16_t days[kNameWidthCount];    // Indices into kNames7 (Sunday first).
  uint16_t plural;                   // Offset of the program in kPluralCode.
  uint16_t overrides_start;          // Run in kCurrencyOverrides, sorted by currency.
  uint16_t overrides_count;
};

struct LocaleTag {
  uint16_t tag;    // Pool offset of the BCP 47 tag ("en", "en-GB").
  uint8_t locale;  // Index into kLocales.
};

extern const char kPool[];
extern const uint16_t kNames12[][12];
extern const uint16_t kNames7[][7];
extern const uint8_t kPluralCode[];
extern const CurrencySymbol kCurrencySymbols[];
extern const CurrencyInfo kCurrencies[];
extern const uint16_t kCurrencyCount;
extern const CurrencyOverride kCurrencyOverrides[];
extern const LocaleData kLocales[];
extern const LocaleTag kLocaleTags[];
extern const uint8_t kLocaleTagCount;

inline const char* pool_str(uint16_t offset) { return kPool + offset; }

}  // namespace detail
}  // namespace locale
}  // namespace a2ui
